import {compute,draft,norm,dedupe} from './engine.js';
import {JobGraph} from './job-graph.js';
import {mergeDemoRows} from './demo-state.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pln=n=>new Intl.NumberFormat('pl-PL',{style:'currency',currency:'PLN',maximumFractionDigits:0}).format(n);
const labels={pending:'Czeka na decyzję',agreed:'Uzgodnione',completed:'Wykonane · bez wpłaty',paid:'Opłacone'};
const titles={overview:['Pulpit','Pulpit',''],sources:['Wiadomości','Wiadomości',''],jobs:['Zlecenia','Zlecenia',''],tasks:['Plan działań','Do zrobienia','']};
let state={rows:[],date:'2026-10-30',replay:0},view='overview',model,demo;
let clarifyingSource=null;
const jobGraph=new JobGraph($('#graph'),{onJob:id=>details(id),onTask:(id,type)=>details(id,type),onGap:record=>{messageDialog(true);clarifyingSource=record.source_id;}});
let timer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function persist(){try{localStorage.setItem('porzadek-mvp-v1',JSON.stringify(state));}catch{toast('Brak miejsca na zapis. Pobierz stan JSON przed zamknięciem.');}}
function go(tab){view=tab;$$('[data-page]').forEach(p=>p.hidden=p.dataset.page!==tab);$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('#crumb').textContent=titles[tab][0];$('#page-title').textContent=titles[tab][1];$('#page-description').textContent=titles[tab][2];$('#page-description').hidden=!titles[tab][2];history.replaceState(null,'','#'+tab);if(tab==='jobs')requestAnimationFrame(()=>jobGraph.layout());}
function sourceCard(r){return `<article class="source-card"><div class="source-meta"><span>${esc(r.source_id)} · ${esc(r.channel)}</span><time>${esc(r.sent_at.slice(5,16).replace('T',' '))}</time></div><h3>${esc(r.conversation_title||'Notatka')} · ${esc(({owner:'właściciel',customer:'klient',worker:'ekipa',supplier:'dostawca'})[r.author_role]||r.author_role)}</h3><p>${esc(r.raw_text)}</p>${(r.attachments||[]).map(a=>`<p class="attachment">↳ ${esc(a.filename)} · tekst niedostępny</p>`).join('')}</article>`;}
function taskRows(limit=model.tasks.length){return model.tasks.slice(0,limit).map(t=>{const j=model.jobs.find(j=>j.id===t.job);return `<div class="task-row"><div class="task-icon">${({decision:'↗',budget:'≠',schedule:'◷',payment:'€'})[t.type]}</div><div class="task-text"><strong>${esc(t.title)}</strong><span>${esc(j.address)} · ${pln(j.amount)}${t.due?' · kontakt '+esc(t.due.slice(5)):''}</span></div><button data-task="${esc(t.id)}">Napisz</button></div>`;}).join('')||'<p class="muted">Brak otwartych spraw w dostępnych danych.</p>';}
function render(){
 model=compute(state.rows,state.date+'T23:59:59+01:00');$('#report-date').value=state.date;
 $('#empty').hidden=state.rows.length>0;$('#app-content').hidden=!state.rows.length;
 $('#nav-count').textContent=model.unique;$('#task-count').textContent=model.tasks.length;
 for(const k of ['pending','agreed','paid'])$('#stat-'+k).textContent=pln(model.totals[k]);
 $('#flow-input').textContent=state.rows.length;$('#flow-unique').textContent=model.unique;$('#flow-jobs').textContent=model.jobs.length;
 $('#dashboard-tasks').innerHTML=taskRows(3);$('#all-tasks').innerHTML='<div class="panel-heading"><h2>Do zrobienia · '+model.tasks.length+'</h2></div>'+taskRows();
 const max=Math.max(...Object.values(model.totals),1);
 $('#bars').innerHTML=[['pending','Wyceny w toku'],['agreed','Uzgodnione prace'],['completed','Wykonane nierozliczone'],['paid','Potwierdzone wpłaty']].map(([k,n])=>`<div class="bar-line"><div class="bar-label"><span>${n}</span><span>${pln(model.totals[k])}</span></div><div class="bar-track"><div class="bar" style="width:${model.totals[k]/max*100}%"></div></div></div>`).join('');
 $('#gap-panel').hidden=!model.gaps.length;
 $('#gap-panel').innerHTML=model.gaps.length?`<div class="gap-content"><h2>Brakuje klienta</h2><p>„${esc(model.gaps[0].raw_text.slice(0,65))}…”</p></div><button class="quiet" id="clarify">Uzupełnij</button>`:'';
 jobGraph.setModel(model,state.date);
 renderSources();$('#replay-steps').innerHTML=['Wyjaśnienie notatki','Akceptacja wyceny','Wykonana praca','Potwierdzona wpłata'].map((n,i)=>`<div class="step ${i<state.replay?'done':''}">${i<state.replay?'✓ ':''}${n}<small>${['30 paź · 08:05','30 paź · 08:10','2 lis · 16:40','3 lis · 10:15'][i]}</small></div>`).join('');
 $('#replay').disabled=state.replay>=demo.events.length;$('#replay').textContent=state.replay>=demo.events.length?'Scenariusz zakończony ✓':'Następne zdarzenie →';
 $('#replay-description').textContent=state.replay?['Właściciel doprecyzował notatkę. Zadanie do Ewy zostało scalone.','Klientka zaakceptowała 4300 zł. Kolejny krok: ustalenie terminu.','Praca wykonana. Kwota czeka na potwierdzenie wpłaty.','Wpłata potwierdzona przez właściciela. Okres raportu obejmuje 3 listopada.'][state.replay-1]:'Przygotowane zdarzenia demo. Zegar przesuwa się jawnie wraz z nimi.';
 persist();
}
function renderSources(){const q=norm($('#search').value);const rows=model.sources.filter(r=>Date.parse(r.sent_at)<=Date.parse(state.date+'T23:59:59+01:00')).filter(r=>!q||norm(r.raw_text+' '+r.conversation_title+' '+r.source_id).includes(q));$('#source-list').innerHTML=rows.slice().reverse().map(sourceCard).join('')||'<p>Brak wiadomości pasujących do wyszukiwania.</p>';}
function details(id,type){const j=model.jobs.find(j=>j.id===id);if(!j)return;$('#detail-title').textContent=j.address+' · '+j.customer;
 $('#detail-body').innerHTML=`<span class="pill ${j.status}">${labels[j.status]}</span><h3>Aktualna kwota</h3><h2>${pln(j.amount)}</h2>${j.excludes.length?'<p class="muted">Poza zakresem: '+esc(j.excludes.join(', '))+'</p>':''}${type?`<h3>Wiadomość do klienta</h3><div class="draft" id="draft-text">${esc(draft(j,type))}</div><button id="copy-draft" class="primary">Kopiuj wiadomość</button><p class="form-note">Skopiuj i wyślij klientowi. Potem dodaj jego odpowiedź.</p>`:''}<details class="detail-fold"><summary>Historia zmian</summary>${j.history.map(h=>{const show=v=>h.field==='amount'?pln(v):h.field==='status'?(labels[v]||v):String(v);return `<div class="history-row">${h.field==='amount'&&h.from===0?'Pierwsza wycena':esc(({amount:'Wycena',status:'Status'})[h.field]||h.field)}: ${h.field==='amount'&&h.from===0?'':esc(show(h.from))+' → '}<strong>${esc(show(h.to))}</strong><br><small>${esc(h.at.slice(0,10))}</small></div>`;}).join('')}</details><details class="detail-fold"><summary>Wiadomości (${j.evidence.length})</summary>${j.evidence.map(s=>model.sources.find(r=>r.source_id===s)).filter(Boolean).reverse().map(sourceCard).join('')}</details>`;
 $('#detail-dialog').showModal();$('#copy-draft')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(draft(j,type));toast('Wiadomość skopiowana.');}catch{toast('Zaznacz i skopiuj treść szkicu.');}});
}
function messageDialog(clarify=false){clarifyingSource=clarify?model.gaps[0]?.source_id:null;$('#message-job').innerHTML=(clarify?'<option value="">Wybierz klienta z notatki</option>':'')+model.jobs.map(j=>`<option value="${esc(j.id)}">${esc(j.address)} · ${esc(j.customer)}</option>`).join('');$('#message-date').value=state.date;$('#message-text').value='';$('#message-author').value=clarify?'owner':'customer';if(clarify){$('#message-text').placeholder='Który klient kryje się pod „panią za piekarnią” i co mamy zrobić?';}else $('#message-text').placeholder='np. tak, potwierdzamy 4300 zł bez kabiny';$('#message-dialog').showModal();}
function append(records){const candidate=[...state.rows,...records];compute(candidate,state.date+'T23:59:59+01:00');state.rows=candidate;render();}
function loadDemo(){state={rows:demo.messages,date:'2026-10-30',replay:0,fixtureVersion:demo.fixture_version};render();go('overview');toast('Wczytano demo: '+state.rows.length+' wpisów, '+model.unique+' źródeł.');}
document.addEventListener('click',e=>{const tab=e.target.closest('[data-tab],[data-goto]');if(tab)go(tab.dataset.tab||tab.dataset.goto);const j=e.target.closest('[data-job]');if(j)details(j.dataset.job);const task=e.target.closest('[data-task]');if(task){const t=model.tasks.find(t=>t.id===task.dataset.task);details(t.job,t.type);}if(e.target.closest('[data-close]'))e.target.closest('dialog').close();if(e.target.closest('#clarify'))messageDialog(true);});
$('#new-message').onclick=()=>model.jobs.length?messageDialog():toast('Najpierw wczytaj demo lub zaimportuj wiadomości.');
$('#search').oninput=renderSources;$('#report-date').onchange=e=>{if(!e.target.value)return;state.date=e.target.value;render();};
$('#message-form').onsubmit=e=>{e.preventDefault();const j=model.jobs.find(j=>j.id===$('#message-job').value);const text=$('#message-text').value.trim();if(!text)return;const r={source_id:'U_'+crypto.randomUUID(),channel:'manual',thread_id:'manual_'+j.id,contact_key:null,conversation_title:j.customer,job_context:j.id,author_role:$('#message-author').value,sent_at:$('#message-date').value+'T12:00:00+01:00',raw_text:text,...(clarifyingSource?{clarifies_source_id:clarifyingSource}:{})};try{append([r]);state.date=$('#message-date').value;render();$('#message-dialog').close();toast('Wiadomość zapisana. Stan przeliczony.');}catch(err){toast(err.message);}};
$('#replay').onclick=()=>{if(state.replay>=demo.events.length)return;const r=demo.events[state.replay];state.rows=[...state.rows,r];state.replay++;state.date=r.sent_at.slice(0,10);render();toast('Dodano '+r.source_id+' · '+r.raw_text.slice(0,75)+'…');};
$('#load-demo').onclick=loadDemo;$('#reset').onclick=()=>{if(confirm('Przywrócić dane demo? Usunie to zmiany zapisane w tej przeglądarce.'))loadDemo();};
$('#import').onclick=()=>$('#file-input').click();$('#file-input').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error('Limit importu wynosi 5 MB.');const text=await file.text();let rows;try{const value=JSON.parse(text);rows=Array.isArray(value)?value:value.messages||value.rows;}catch{rows=text.trim().split(/\r?\n/).map(JSON.parse);}if(!Array.isArray(rows))throw Error('Wybierz JSONL lub tablicę wiadomości JSON.');dedupe(rows);const uniqueBefore=dedupe(state.rows).length;append(rows);toast('Dodano '+(dedupe(state.rows).length-uniqueBefore)+' nowych źródeł. Powtórki nie zmieniają kwot.');}catch(err){toast('Import zatrzymany: '+err.message);}finally{e.target.value='';}};
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({date:state.date,rows:state.rows,report:model},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='porzadek-stan.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
window.addEventListener('hashchange',()=>{const tab=location.hash.slice(1);if(titles[tab])go(tab);});
try{const response=await fetch('./demo.json');if(!response.ok)throw Error('Nie udało się wczytać demo.');demo=await response.json();try{const stored=JSON.parse(localStorage.getItem('porzadek-mvp-v1'));if(stored&&Array.isArray(stored.rows)&&/^\d{4}-\d{2}-\d{2}$/.test(stored.date)){dedupe(stored.rows);state=stored;}else state.rows=demo.messages;}catch{state.rows=demo.messages;}const seed=demo.messages.find(r=>r.source_id==='S01');if(state.fixtureVersion!==demo.fixture_version&&state.rows.some(r=>r.source_id==='S01'&&r.raw_text===seed?.raw_text)){state.rows=mergeDemoRows(state.rows,demo.messages);state.fixtureVersion=demo.fixture_version;}render();go(titles[location.hash.slice(1)]?location.hash.slice(1):'overview');}catch(err){$('#empty').hidden=false;$('#app-content').hidden=true;$('#empty').textContent=err.message;}
